<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/functions.php';zorunlu_rol('admin','hakem');
$macId=(int)($_GET['mac_id']??$_POST['mac_id']??0);$set=(int)($_GET['set']??$_POST['set']??0);$s=$pdo->prepare('SELECT m.*,a.takim_adi ev,b.takim_adi dep,ms.ev_sahibi_set_puani,ms.deplasman_set_puani,ms.kazanan FROM maclar m JOIN takimlar a ON a.id=m.ev_sahibi_id JOIN takimlar b ON b.id=m.deplasman_id JOIN mac_setleri ms ON ms.mac_id=m.id WHERE m.id=? AND ms.set_no=?');$s->execute([$macId,$set]);$mac=$s->fetch();if(!$mac||$mac['ev_sahibi_set_puani']!=$mac['deplasman_set_puani']||$mac['kazanan']){flash_set('hata','Bu set için eşitlik bozma gerekmiyor.');redirect(BASE_URL.'/admin/mac-skor.php?mac_id='.$macId.'&set='.$set);}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!csrf_check($_POST['csrf']??'')){flash_set('hata','Güvenlik doğrulaması başarısız.');redirect(BASE_URL.'/admin/esitlik-bozma.php?mac_id='.$macId.'&set='.$set);}$ev=max(0,min(210,(int)($_POST['ev_puan']??0)));$dep=max(0,min(210,(int)($_POST['dep_puan']??0)));$c=$pdo->prepare("SELECT COUNT(*) FROM esitlik_bozma_atislari WHERE kaynak='lig' AND mac_id=? AND set_no=?");$c->execute([$macId,$set]);$tur=(int)$c->fetchColumn()+1;$pdo->prepare("INSERT INTO esitlik_bozma_atislari(kaynak,mac_id,set_no,tur_no,ev_puan,dep_puan) VALUES('lig',?,?,?,?,?)")->execute([$macId,$set,$tur,$ev,$dep]);if($ev===$dep){flash_set('hata','Eşitlik devam ediyor; yeniden 7 ok toplamı girin.');redirect(BASE_URL.'/admin/esitlik-bozma.php?mac_id='.$macId.'&set='.$set);}$pdo->prepare('UPDATE mac_setleri SET kazanan=? WHERE mac_id=? AND set_no=?')->execute([$ev>$dep?'ev':'dep',$macId,$set]);flash_set('basari','Eşitlik bozuldu, set galibi belirlendi.');redirect(BASE_URL.'/admin/mac-skor.php?mac_id='.$macId.'&set='.min(SET_SAYISI,$set+1));}
$c=$pdo->prepare("SELECT * FROM esitlik_bozma_atislari WHERE kaynak='lig' AND mac_id=? AND set_no=? ORDER BY tur_no");$c->execute([$macId,$set]);$turlar=$c->fetchAll();ob_start();?>
<div class="card"><div class="card-head"><h2><?= $set ?>. Set — Eşitlik Bozma</h2><span class="badge">Normal set: <?= (int)$mac['ev_sahibi_set_puani'] ?> - <?= (int)$mac['deplasman_set_puani'] ?></span></div><p class="muted">İsimsiz Eşitlik Bozma Sporcusu, her takım adına 7 ok atar. Bu puanlar averaj ve sezon istatistiklerine eklenmez.</p><form method="post" class="form"><?= csrf_field() ?><input type="hidden" name="mac_id" value="<?= $macId ?>"><input type="hidden" name="set" value="<?= $set ?>"><div class="grid-2"><label><?= e($mac['ev']) ?> — Eşitlik Bozma Sporcusu<input name="ev_puan" type="number" min="0" max="210" required></label><label><?= e($mac['dep']) ?> — Eşitlik Bozma Sporcusu<input name="dep_puan" type="number" min="0" max="210" required></label></div><button class="btn btn-primary">Eşitliği Boz</button></form><?php foreach($turlar as $t): ?><p class="muted">Ek atış <?= (int)$t['tur_no'] ?>: <?= (int)$t['ev_puan'] ?> - <?= (int)$t['dep_puan'] ?><?= $t['ev_puan']==$t['dep_puan']?' · eşitlik sürüyor':'' ?></p><?php endforeach; ?></div>
<?php $admin_baslik='Eşitlik Bozma';$admin_aktif='skor';$admin_icerik=ob_get_clean();require __DIR__.'/partials/layout.php';?>
